async function courseJson<T>(path: string, init?: RequestInit): Promise<T> {
	const response = await fetch(`/api/courses${path}`, {
		...init,
		headers: {
			...(init?.body ? { "content-type": "application/json" } : {}),
			...init?.headers,
		},
